      case 6: try { try decoder.decodeSingularStringField(value: &self.policyVersion) }()
      case 7: try { try decoder.decodeSingularStringField(value: &self.aclVersion) }()
      default: break
      }
    }
  }

  public func traverse<V: SwiftProtobuf.Visitor>(visitor: inout V) throws {
    // The use of inline closures is to circumvent an issue where the compiler
    // allocates stack space for every if/case branch local when no optimizations
    // are enabled. https://github.com/apple/swift-protobuf/issues/1034 and
    // https://github.com/apple/swift-protobuf/issues/1182
    if self.effect != .unspecified {
      try visitor.visitSingularEnumField(value: self.effect, fieldNumber: 1)
    }
    if self.reason != .unspecified {
      try visitor.visitSingularEnumField(value: self.reason, fieldNumber: 2)
    }
    if self.action != .unspecified {
      try visitor.visitSingularEnumField(value: self.action, fieldNumber: 3)
    }
    try { if let v = self._resource {
      try visitor.visitSingularMessageField(value: v, fieldNumber: 4)
    } }()
    try { if let v = self._actor {
      try visitor.visitSingularMessageField(value: v, fieldNumber: 5)
    } }()
    if !self.policyVersion.isEmpty {
      try visitor.visitSingularStringField(value: self.policyVersion, fieldNumber: 6)
    }
    if !self.aclVersion.isEmpty {
      try visitor.visitSingularStringField(value: self.aclVersion, fieldNumber: 7)
    }
    try unknownFields.traverse(visitor: &visitor)
  }

  public static func ==(lhs: AuthorizationDecision, rhs: AuthorizationDecision) -> Bool {
    if lhs.effect != rhs.effect {return false}
    if lhs.reason != rhs.reason {return false}
    if lhs.action != rhs.action {return false}
    if lhs._resource != rhs._resource {return false}
    if lhs._actor != rhs._actor {return false}
    if lhs.policyVersion != rhs.policyVersion {return false}
    if lhs.aclVersion != rhs.aclVersion {return false}
    if lhs.unknownFields != rhs.unknownFields {return false}
    return true
  }
}
